using Servicio.RetazoMarket.Business.DTOs.Pedido;
namespace Servicio.RetazoMarket.Business.Validators;public static class PedidoValidator {public static IReadOnlyCollection<string> Validar(CrearPedidoRequest r)=>r is null?["La solicitud no puede ser nula."]:Campos(r.id_cliente,r.id_metodo,r.entrega_fisica,r.detalles);public static IReadOnlyCollection<string> Validar(ActualizarPedidoRequest r){if(r is null)return ["La solicitud no puede ser nula."];var e=Campos(r.id_cliente,r.id_metodo,r.entrega_fisica,r.detalles).ToList();if(r.id_pedido<=0)e.Insert(0,"El id del pedido es inválido.");return e;}public static IReadOnlyCollection<string> ValidarFiltro(PedidoFiltroRequest r){var e=new List<string>();if(r is null)return ["El filtro no puede ser nulo."];if(!string.IsNullOrWhiteSpace(r.estado)&&r.estado.Trim().ToUpperInvariant() is not("PEN" or "REA"))e.Add("El estado debe ser PEN o REA.");if(r.fecha_desde_utc>r.fecha_hasta_utc)e.Add("La fecha desde no puede superar a la fecha hasta.");if(r.page_number<=0)e.Add("El número de página debe ser mayor que cero.");if(r.page_size<=0||r.page_size>100)e.Add("El tamaño de página debe estar entre 1 y 100.");return e;}private static IReadOnlyCollection<string> Campos(int cliente,int metodo,string? entrega,IReadOnlyCollection<DetallePedidoRequest>? detalles){var e=new List<string>();if(cliente<=0)e.Add("El cliente es obligatorio.");if(metodo<=0)e.Add("El método de pago es obligatorio.");if(entrega?.Trim().ToUpperInvariant() is not("S" or "N"))e.Add("entrega_fisica debe ser S o N.");if(detalles is null||detalles.Count==0){e.Add("El pedido debe contener al menos un detalle.");return e;}if(detalles.Any(x=>x.id_producto<=0||x.cantidad<=0))e.Add("Todos los detalles requieren producto y cantidad positiva.");if(detalles.GroupBy(x=>x.id_producto).Any(x=>x.Count()>1))e.Add("Un producto no puede repetirse dentro del pedido.");if(detalles.Any(x=>x.personalizaciones.GroupBy(p=>p.id_opcion).Any(g=>g.Count()>1)))e.Add("Una personalización no puede repetirse en el mismo detalle.");return e;}}
